WITH ValidPayments AS (SELECT *, CASE WHEN status = 'SUCCESS' THEN 1 ELSE 0 END AS is_success FROM payments WHERE method = 'cash'), agg AS (SELECT status, YEAR(paid_at) AS paid_year, ROUND((100 * SUM(CASE WHEN status = 'FAILED' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_failed, COUNT(is_success) AS is_success_count FROM ValidPayments GROUP BY status, YEAR(paid_at)) SELECT status, paid_year, pct_failed, is_success_count FROM agg ORDER BY pct_failed DESC, paid_year;
